const hoy = new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
const valido = (v) => v !== undefined && v !== null && v !== '' && !['null', 'n/a'].includes(String(v).toLowerCase());
const esc = (v) => String(v ?? 'N/D').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

return $input.all()
  .filter(({ json }) => String(json.initDate || '').slice(0, 10) === hoy && String(json.status || '').toLowerCase() === 'finished')
  .map((item) => {
    const d = item.json;
    const seriales = Object.entries(d)
      .filter(([k, v]) => (k.toUpperCase().includes('SERIAL') || /^ESCANER_BOLSA_\d+$/.test(k.toUpperCase())) && valido(v))
      .map(([k, v]) => '. <b>' + esc(k.replace(/^ESCANER_/i, 'ESC?NER_').replaceAll('_', ' ')) + ':</b> ' + esc(v))
      .join('\n');
    const tipoRecaudo = valido(d.TIPO_DE_RECAUDO) ? esc(d.TIPO_DE_RECAUDO) : 'N/D';
    const esCaja = String(d.TIPO_DE_RECAUDO || '').trim().toUpperCase() === 'CAJA';
    const tipoTraslado = esCaja && valido(d.TIPO_DE_TRASLADO) ? esc(d.TIPO_DE_TRASLADO) : '';
    const esEntrega = String(d.TIPO_DE_TRASLADO || '').trim().toUpperCase() === 'ENTREGA';
    const lugarEntrega = esEntrega && valido(d.LUGAR_DE_ENTREGA) ? esc(d.LUGAR_DE_ENTREGA) : '';
    const pdv = d.visit_point_name || d.visit_point_identification || 'N/D';
    d.mensaje_telegram = [
      '\u2705 <b>VISITA FINALIZADA - MONITOREO</b>',
      '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501',
      '\uD83C\uDD94 <b>Visita:</b> ' + esc(d.visitID),
      '\uD83D\uDC64 <b>Usuario:</b> ' + esc(d.userName),
      '\uD83D\uDCCD <b>PDV:</b> ' + esc(pdv),
      '\uD83E\uDDFE <b>Tipo de recaudo:</b> ' + tipoRecaudo,
      tipoTraslado ? '\uD83D\uDE9A <b>Tipo de traslado:</b> ' + tipoTraslado : '',
      lugarEntrega ? '\uD83D\uDCCC <b>Lugar de entrega:</b> ' + lugarEntrega : '',
      '\uD83D\uDCC5 <b>Fecha y hora:</b> ' + esc(d.initDate) + ' ? ' + esc(d.endHour),
      seriales ? '\n\uD83D\uDCE6 <b>SERIALES REGISTRADOS</b>\n' + seriales : ''
    ].filter(Boolean).join('\n');
    return item;
  });

