CREATE TABLE IF NOT EXISTS `gelsa-datarutas-prod.formularios.log_notificaciones_telegram` (
  visitID STRING NOT NULL,
  fecha_envio TIMESTAMP NOT NULL,
  estado STRING NOT NULL
);

MERGE `gelsa-datarutas-prod.formularios.log_notificaciones_telegram` T
USING (
  SELECT '{{ $("Code in JavaScript").item.json.notificacion_id || $("Code in JavaScript").item.json.visitID }}' AS visitID
) S
ON T.visitID = S.visitID
WHEN NOT MATCHED THEN
  INSERT (visitID, fecha_envio, estado)
  VALUES (S.visitID, CURRENT_TIMESTAMP(), 'ENVIADO');

