const hoy = new Date().toLocaleDateString('en-CA', {
  timeZone: 'America/Bogota',
});

const normalizar = (valor) => String(valor ?? '').trim();

const escaparHtml = (valor) =>
  String(valor ?? 'N/D')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const esSerialValido = (valor) => {
  const serial = normalizar(valor).toUpperCase();

  return (
    serial !== '' &&
    serial !== '0' &&
    !/^0+$/.test(serial) &&
    !['NULL', 'N/A', '[NULL]', 'SIN SERIAL'].includes(serial)
  );
};

// ============================================================
// EXTRAER TODOS LOS SERIALES DE UN CAMPO
// ============================================================

const extraerSeriales = (valor) => {
  if (valor === undefined || valor === null) return [];

  // Si BigQuery/n8n entrega arreglo
  if (Array.isArray(valor)) {
    return valor.flatMap(extraerSeriales);
  }

  // Si entrega objeto
  if (typeof valor === 'object') {
    if (Object.prototype.hasOwnProperty.call(valor, 'value')) {
      const candidato =
        normalizar(valor.value).toUpperCase() === 'TRUE'
          ? valor.key
          : valor.value;

      return extraerSeriales(candidato);
    }

    return Object.values(valor).flatMap(extraerSeriales);
  }

  const texto = normalizar(valor);

  if (!texto) return [];

  // Si viene JSON almacenado como texto
  if (texto.startsWith('[') || texto.startsWith('{')) {
    try {
      return extraerSeriales(JSON.parse(texto));
    } catch (_) {
      // Sigue trat?ndolo como texto.
    }
  }

  /*
   * IMPORTANTE:
   * STRING_AGG de BigQuery normalmente puede entregar:
   *
   * SERIAL1,SERIAL2,SERIAL3
   *
   * y en otros campos:
   *
   * SERIAL1 ? SERIAL2 ? SERIAL3
   *
   * Aqu? se separan TODOS.
   */
  return texto
    .split(/[?,;\n|]+/)
    .map(normalizar)
    .filter(esSerialValido);
};

// ============================================================
// CONSULTAS 2, 3 Y 6
// ============================================================

const camposOrigen236 = [
  // CONSULTA 2 - CDA
  'ESCANER_SERIAL_BOLSA_CDA',
  'SERIAL_BOLSA_CDA',

  // CONSULTA 3 - DISTRIBUCI?N
  'SERIAL_BOLSA_DISTR',
  'ESCANER_SERIAL_BOLSA_DISTR',

  // CONSULTA 6 - CAJA
  'ESCANER_SERIAL_BOLSA',
  'SERIAL_BOLSA'
];

// ============================================================
// CONSULTAS 4 Y 5
// SE CONSERVA SU L?GICA
// ============================================================

const esCampoSerial45 = (campo) => {
  const nombre = normalizar(campo).toUpperCase();

  return (
    nombre === 'SERIALES_ENTREGA' ||

    /^ESCANER_SERIAL(?:_BOLSA)?_\d+$/.test(nombre) ||
    /^SERIAL_BOLSA_\d+$/.test(nombre) ||
    /^ESCANER_BOLSA_\d+$/.test(nombre) ||
    /^SERIAL_BOLSA_TESORERIA_\d+$/.test(nombre)
  );
};

const etiquetaSerial = (campo) =>
  String(campo)
    .replace(/^ESCANER_/i, 'ESC?NER_')
    .replace(/_/g, ' ');

// ============================================================
// AGRUPAR POR VISITID + DESTINATARIO
// ============================================================

const visitas = new Map();

for (const item of $input.all()) {
  const d = item.json ?? {};

  const fechaVisita = normalizar(d.initDate).slice(0, 10);
  const estado = normalizar(d.status).toLowerCase();
  const visitID = normalizar(d.visitID);

  // Solo visitas de hoy
  if (fechaVisita !== hoy) continue;

  // Solo visitas finalizadas
  if (estado !== 'finished') continue;

  if (!visitID) continue;

  const chatID = normalizar(
    d.telegram_chat_id ??
    d.Chat_ID ??
    d.chat_id
  );

  /*
   * IMPORTANTE:
   * Un VisitID puede enviarse a varios destinatarios.
   *
   * Por eso la agrupaci?n es:
   *
   * VisitID + Chat_ID
   */
  const claveVisita = `${visitID}|${chatID || 'SIN_CHAT'}`;

  if (!visitas.has(claveVisita)) {
    visitas.set(claveVisita, {
      base: d,

      // Consultas 2, 3 y 6
      seriales236: [],
      vistos236: new Set(),

      // Consultas 4 y 5
      seriales45: [],
      vistos45: new Set(),
    });
  }

  const visita = visitas.get(claveVisita);

  // ==========================================================
  // CONSULTAS 2, 3 Y 6
  // ACUMULAR TODOS LOS SERIALES DEL VISITID
  // ==========================================================

  for (const campo of camposOrigen236) {

    const valor = d[campo];

    const serialesEncontrados = extraerSeriales(valor);

    for (const serial of serialesEncontrados) {

      const serialLimpio = normalizar(serial);

      if (!esSerialValido(serialLimpio)) continue;

      /*
       * La llave es ?nicamente el serial.
       *
       * As?, si el mismo serial aparece en:
       *
       * ESCANER_SERIAL_BOLSA_CDA
       * y
       * SERIAL_BOLSA_CDA
       *
       * solamente se muestra una vez.
       */
      const claveSerial = serialLimpio.toUpperCase();

      if (visita.vistos236.has(claveSerial)) {
        continue;
      }

      visita.vistos236.add(claveSerial);

      visita.seriales236.push({
        campo,
        serial: serialLimpio,
      });
    }
  }

  // ==========================================================
  // CONSULTAS 4 Y 5
  // SE CONSERVA LA L?GICA
  // ==========================================================

  for (const [campo, valor] of Object.entries(d)) {

    if (!esCampoSerial45(campo)) continue;

    const serialesEncontrados = extraerSeriales(valor);

    for (const serial of serialesEncontrados) {

      const serialLimpio = normalizar(serial);

      if (!esSerialValido(serialLimpio)) continue;

      const claveSerial =
        `${normalizar(campo).toUpperCase()}|${serialLimpio.toUpperCase()}`;

      if (visita.vistos45.has(claveSerial)) {
        continue;
      }

      visita.vistos45.add(claveSerial);

      visita.seriales45.push({
        campo,
        serial: serialLimpio,
      });
    }
  }
}

// ============================================================
// GENERAR MENSAJE
// ============================================================

return [...visitas.values()].map(
  ({ base: d, seriales236, seriales45 }) => {

    // ========================================================
    // SERIALES CONSULTAS 2, 3 Y 6
    // ========================================================

    const textoSeriales236 = seriales236
      .map(({ serial }) =>
        `. ${escaparHtml(serial)}`
      )
      .join('\n');

    // ========================================================
    // SERIALES CONSULTAS 4 Y 5
    // ========================================================

    const textoSeriales45 = seriales45
      .map(({ campo, serial }) =>
        campo === 'SERIALES_ENTREGA'
          ? `. ${escaparHtml(serial)}`
          : `. <b>${escaparHtml(etiquetaSerial(campo))}:</b> ${escaparHtml(serial)}`
      )
      .join('\n');
    // INFORMACI?N GENERAL
    // ========================================================

    const tipoRecaudoOriginal =
      normalizar(d.TIPO_DE_RECAUDO);

    const tipoRecaudo =
      tipoRecaudoOriginal
        ? escaparHtml(tipoRecaudoOriginal)
        : 'N/D';

    const esCaja =
      tipoRecaudoOriginal.toUpperCase() === 'CAJA';

    const tipoTrasladoOriginal =
      normalizar(d.TIPO_DE_TRASLADO);

    const tipoTraslado =
      esCaja && tipoTrasladoOriginal
        ? escaparHtml(tipoTrasladoOriginal)
        : '';

    const esEntrega =
      tipoTrasladoOriginal.toUpperCase() === 'ENTREGA';

    const lugarEntrega =
      esEntrega && normalizar(d.LUGAR_DE_ENTREGA)
        ? escaparHtml(d.LUGAR_DE_ENTREGA)
        : '';

    const pdv =
      normalizar(d.visit_point_name) ||
      normalizar(d.visit_point_identification) ||
      'N/D';

    // ========================================================
    // MENSAJE TELEGRAM
    // ========================================================

    const mensaje = [
      '\u2705 <b>VISITA FINALIZADA</b>',
      '\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501',

      `\uD83C\uDD94 <b>Visita:</b> ${escaparHtml(d.visitID)}`,

      `\uD83D\uDC64 <b>Usuario:</b> ${escaparHtml(
        d.userName || 'N/D'
      )}`,

      `\uD83D\uDCCD <b>PDV:</b> ${escaparHtml(pdv)}`,

      `\uD83E\uDDFE <b>Tipo de recaudo:</b> ${tipoRecaudo}`,

      tipoTraslado
        ? `\uD83D\uDE9A <b>Tipo de traslado:</b> ${tipoTraslado}`
        : '',

      lugarEntrega
        ? `\uD83D\uDCCC <b>Lugar de entrega:</b> ${lugarEntrega}`
        : '',

      `\uD83D\uDCC5 <b>Fecha y hora:</b> ${
        escaparHtml(d.initDate || 'N/D')
      } \u00B7 ${
        escaparHtml(d.endHour || 'N/D')
      }`,

      textoSeriales236
        ? `\n\uD83D\uDCE6 <b>SERIALES REGISTRADOS (${seriales236.length})</b>\n${textoSeriales236}`
        : '',

      textoSeriales45
        ? `\n\uD83D\uDCE6 <b>SERIALES ENTREGA</b>\n${textoSeriales45}`
        : '',
    ]
      .filter(Boolean)
      .join('\n');
    return {
      json: {
        ...d,

        telegram_chat_id:
          d.telegram_chat_id ??
          d.Chat_ID ??
          d.chat_id ??
          null,

        destinatario_nombre:
          d.destinatario_nombre ??
          d.Nombre_Usuario ??
          '',

        cantidad_seriales_236:
          seriales236.length,

        seriales_236:
          seriales236.map(x => x.serial),

        mensaje_telegram: mensaje,
      },
    };
  }
);

const items = $input.all().map(i => i.json);
if (!items.length) return [];

const normalizar = (v) => String(v ?? '').trim().toUpperCase();
const esSerialValido = (v) => {
  const s = normalizar(v);
  return s !== '' && s !== '0' && !/^0+$/.test(s) && !['NULL', 'N/A', 'SIN SERIAL', '[NULL]'].includes(s);
};
const esc = (v) => String(v ?? 'N/D').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const extraer = (valor) => {
  if (valor === undefined || valor === null) return [];
  if (Array.isArray(valor)) return valor.flatMap(extraer);
  if (typeof valor === 'object') return Object.values(valor).flatMap(extraer);
  const texto = String(valor).trim();
  if (!texto) return [];
  if (texto.startsWith('[') || texto.startsWith('{')) {
    try { return extraer(JSON.parse(texto)); } catch (_) {}
  }
  return texto.split(/[|,;\n]+/).map(normalizar).filter(esSerialValido);
};

const camposOrigen = [
  'ESCANER_SERIAL_BOLSA_CDA', 'SERIAL_BOLSA_CDA',
  'SERIAL_BOLSA_DISTR', 'ESCANER_SERIAL_BOLSA_DISTR',
  'ESCANER_SERIAL_BOLSA', 'SERIAL_BOLSA'
];
const esCampoValidacion = (k) =>
  /^ESCANER_SERIAL(?:_BOLSA)?_\d+$/.test(k) ||
  /^SERIAL_BOLSA_\d+$/.test(k) ||
  /^ESCANER_BOLSA_\d+$/.test(k) ||
  /^SERIAL_BOLSA_TESORERIA_\d+$/.test(k) ||
  k === 'SERIALES_ENTREGA';

// Consultas 4 y 5 llegan consolidadas como "pregunta: serial | ...".
// Se conserva solamente el valor del serial para compararlo con consultas 2, 3 y 6.
const extraerSerialesEntrega = (valor) => String(valor ?? '')
  .split('|')
  .flatMap(parte => extraer(parte.includes(':') ? parte.slice(parte.indexOf(':') + 1) : parte));

// Consultas 4 y 5 forman un unico universo de seriales finalizados.
const entregados = new Set(items.flatMap(d =>
  Object.entries(d)
    .filter(([k]) => esCampoValidacion(k))
    .flatMap(([k, v]) => k === 'SERIALES_ENTREGA' ? extraerSerialesEntrega(v) : extraer(v))
));

const fechaDetalle = new Intl.DateTimeFormat('es-CO', {
  timeZone: 'America/Bogota', day: '2-digit', month: '2-digit', year: 'numeric'
}).format(new Date());

// Un bloque por VisitID, incluso si la visita tiene varios seriales o varias filas de origen.
const grupos = new Map();
for (const d of items) {
  const chat = String(d.monitor_chat_id || '').trim();
  if (!chat || !d.visitID) continue;
  if (!grupos.has(chat)) grupos.set(chat, { chat, corte: d.corte, visitas: new Map() });
  const grupo = grupos.get(chat);
  const id = String(d.visitID);
  if (!grupo.visitas.has(id)) {
    const hora = String(d.endHour || d.initHour || '00:00').slice(0, 5);
    grupo.visitas.set(id, {
      orden: String(d.initDate || '') + ' ' + hora,
      hora,
      usuario: d.userName || 'N/D',
      pdv: d.visit_point_name || d.visit_point_identification || 'N/D',
      seriales: [], vistos: new Set()
    });
  }
  const visita = grupo.visitas.get(id);
  for (const campo of camposOrigen) {
    for (const serial of extraer(d[campo])) {
      if (visita.vistos.has(serial)) continue;
      visita.vistos.add(serial);
      visita.seriales.push(serial);
    }
  }
}

const salida = [];
const LIMITE = 3600;
for (const grupo of grupos.values()) {
  const visitas = [...grupo.visitas.values()]
    .filter(v => v.seriales.length)
    .sort((a, b) => a.orden.localeCompare(b.orden));
  if (!visitas.length) continue;

  const finCorte = String(grupo.corte || '13:00');
  const rango = (finCorte === '19:00' ? '13:00' : '05:00') + ' a ' + finCorte;
  const encabezado = '\uD83D\uDCCB <b>Detalle (' + fechaDetalle + ')</b>\n\uD83D\uDD50 <b>Corte:</b> ' + rango + '\n\n';
  const bloques = visitas.map(v => {
    const lineasSerial = v.seriales.map(s =>
      '. ' + esc(s) + ' - ' + (entregados.has(s) ? 'Finalizado \u2705' : 'Pendiente \u26A0\uFE0F')
    ).join('\n');
    return v.hora + ' - ' + esc(v.usuario) + ' - ' + esc(v.pdv) + '\n' + lineasSerial;
  });

  const partes = [];
  let actual = encabezado;
  for (const bloque of bloques) {
    const texto = bloque + '\n\n';
    if (actual.length + texto.length > LIMITE && actual !== encabezado) {
      partes.push(actual.trimEnd());
      actual = encabezado + texto;
    } else {
      actual += texto;
    }
  }
  if (actual !== encabezado) partes.push(actual.trimEnd());

  partes.forEach((mensaje, index) => {
    const total = partes.length;
    salida.push({ json: {
      telegram_chat_id: grupo.chat,
      mensaje_telegram: (total > 1 ? '\uD83D\uDCC4 <b>Parte ' + (index + 1) + '/' + total + '</b>\n' : '') + mensaje,
      fecha_reporte: new Date().toLocaleDateString('en-CA', { timeZone: 'America/Bogota' }),
      corte: grupo.corte,
      parte: index + 1,
      total_partes: total
    }});
  });
}
return salida;
